const { Given, When, Then, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const path = require('path');
const fs = require('fs');

let window;
let document;

function loadApp() {
  window = new Window({ url: 'http://localhost/' });
  document = window.document;

  const html = fs.readFileSync(
    path.resolve(__dirname, '../../index.html'),
    'utf8'
  );

  // Remove script tags that load external files (those run in real browser context)
  // We'll manually handle app logic
  const cleaned = html.replace(
    /<script[\s\S]*?<\/script>/g,
    ''
  );

  document.write(cleaned);
  document.close();

  // Set up localStorage mock through happy-dom
  window.localStorage.clear();
}

function getTodoList() {
  return document.querySelector('.todo-list');
}

function getTodoItems() {
  const list = getTodoList();
  if (!list) return [];
  return list.querySelectorAll('li');
}

function getTodoCount() {
  const strong = document.querySelector('.todo-count strong');
  if (!strong) return 0;
  return parseInt(strong.textContent, 10);
}

function findTodoItem(title) {
  const items = getTodoItems();
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent.trim() === title) {
      return item;
    }
  }
  return null;
}

function getNewTodoInput() {
  return document.querySelector('.new-todo');
}

function getMainSection() {
  return document.querySelector('.main');
}

function getFooter() {
  return document.querySelector('.footer');
}

function getToggleAll() {
  return document.querySelector('.toggle-all');
}

function getClearCompleted() {
  return document.querySelector('.clear-completed');
}

function getTodoCountElement() {
  return document.querySelector('.todo-count');
}

Before(function () {
  loadApp();
});

After(function () {
  if (window) {
    window.close();
  }
});

// --- Background: Given the app is loaded ---
Given('the app is loaded', function () {
  loadApp();
});

// --- New todos ---
Given('the todo input is focused', function () {
  const input = getNewTodoInput();
  // Focus the input
  input.focus();
});

When('the user types {string} and presses Enter', function (text) {
  const input = getNewTodoInput();
  input.value = text;
  const event = new window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(event);
});

Then('the todo list shows {int} item', function (count) {
  const items = getTodoItems();
  if (items.length !== count) {
    throw new Error(
      `Expected ${count} items, got ${items.length}`
    );
  }
});

Then('the new todo has the title {string}', function (title) {
  const items = getTodoItems();
  if (items.length === 0) {
    throw new Error('No todo items found');
  }
  const label = items[items.length - 1].querySelector('label');
  if (!label) {
    throw new Error('No label found in todo item');
  }
  if (label.textContent.trim() !== title) {
    throw new Error(
      `Expected title "${title}", got "${label.textContent.trim()}"`
    );
  }
});

Then('the todo input is cleared', function () {
  const input = getNewTodoInput();
  if (input.value !== '') {
    throw new Error(`Expected empty input, got "${input.value}"`);
  }
});

Then('the todo list is empty', function () {
  const items = getTodoItems();
  if (items.length !== 0) {
    throw new Error(
      `Expected empty list, got ${items.length} items`
    );
  }
});

// --- No todos state ---
Given('the todo list is empty', function () {
  loadApp();
  // Ensure no todos
});

Then('the main section is hidden', function () {
  const main = getMainSection();
  if (main && main.style.display !== 'none' && window.getComputedStyle(main).display !== 'none') {
    // Check if hidden by class or display
    if (main.classList.contains('hidden') === false) {
      throw new Error('Main section is not hidden');
    }
  }
});

Then('the footer is hidden', function () {
  const footer = getFooter();
  if (footer && footer.style.display !== 'none' && window.getComputedStyle(footer).display !== 'none') {
    if (footer.classList.contains('hidden') === false) {
      throw new Error('Footer is not hidden');
    }
  }
});

// --- Todos present ---
Given('the todo list has {int} item', function (count) {
  loadApp();
  // Add the specified number of items
  for (let i = 0; i < count; i++) {
    const input = getNewTodoInput();
    input.value = `Item ${i + 1}`;
    const event = new window.KeyboardEvent('keydown', {
      key: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true
    });
    input.dispatchEvent(event);
  }
});

Given('the todo list has {int} item {string}', function (count, title) {
  loadApp();
  const input = getNewTodoInput();
  input.value = title;
  const event = new window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(event);
});

Given('the todo list has items {string}, {string}, {string}', function (item1, item2, item3) {
  loadApp();
  for (const title of [item1, item2, item3]) {
    const input = getNewTodoInput();
    input.value = title;
    const event = new window.KeyboardEvent('keydown', {
      key: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true
    });
    input.dispatchEvent(event);
  }
});

Given('the todo list has items {string}, {string}', function (item1, item2) {
  loadApp();
  for (const title of [item1, item2]) {
    const input = getNewTodoInput();
    input.value = title;
    const event = new window.KeyboardEvent('keydown', {
      key: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true
    });
    input.dispatchEvent(event);
  }
});

Then('the main section is visible', function () {
  const main = getMainSection();
  if (!main) {
    throw new Error('Main section not found');
  }
  // Check it's not hidden
  if (main.style.display === 'none') {
    throw new Error('Main section is hidden');
  }
});

Then('the footer is visible', function () {
  const footer = getFooter();
  if (!footer) {
    throw new Error('Footer not found');
  }
  if (footer.style.display === 'none') {
    throw new Error('Footer is hidden');
  }
});

// --- Completing todos ---
Given('the todo list has {int} completed item {string}', function (count, title) {
  loadApp();
  const input = getNewTodoInput();
  input.value = title;
  const event = new window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(event);

  // Toggle it to completed
  const item = findTodoItem(title);
  if (item) {
    const toggle = item.querySelector('.toggle');
    if (toggle) {
      toggle.checked = true;
      toggle.dispatchEvent(new window.Event('change', { bubbles: true }));
    }
  }
});

When('the user clicks the toggle on {string}', function (title) {
  const item = findTodoItem(title);
  if (!item) {
    throw new Error(`Todo "${title}" not found`);
  }
  const toggle = item.querySelector('.toggle');
  if (!toggle) {
    throw new Error(`Toggle not found for "${title}"`);
  }
  toggle.click();
});

Then('the todo {string} has the completed class', function (title) {
  const item = findTodoItem(title);
  if (!item) {
    throw new Error(`Todo "${title}" not found`);
  }
  if (!item.classList.contains('completed')) {
    throw new Error(`Todo "${title}" does not have completed class`);
  }
});

Then('its checkbox is checked', function () {
  // Use the last todo item that was toggled
  const items = getTodoItems();
  if (items.length === 0) {
    throw new Error('No todo items');
  }
  const toggle = items[items.length - 1].querySelector('.toggle');
  if (!toggle || !toggle.checked) {
    throw new Error('Checkbox is not checked');
  }
});

Then('the todo {string} does not have the completed class', function (title) {
  const item = findTodoItem(title);
  if (!item) {
    throw new Error(`Todo "${title}" not found`);
  }
  if (item.classList.contains('completed')) {
    throw new Error(`Todo "${title}" has completed class`);
  }
});

Then('its checkbox is not checked', function () {
  const items = getTodoItems();
  if (items.length === 0) {
    throw new Error('No todo items');
  }
  const toggle = items[items.length - 1].querySelector('.toggle');
  if (!toggle || toggle.checked) {
    throw new Error('Checkbox is checked');
  }
});

// --- Toggle all ---
When('the user clicks the toggle-all checkbox', function () {
  const toggleAll = getToggleAll();
  if (!toggleAll) {
    throw new Error('Toggle-all checkbox not found');
  }
  toggleAll.click();
});

Then('all todos are marked as completed', function () {
  const items = getTodoItems();
  for (const item of items) {
    if (!item.classList.contains('completed')) {
      throw new Error('Not all todos are completed');
    }
  }
});

Given('all todos are completed', function () {
  loadApp();
  // Add items then toggle all
  const input = getNewTodoInput();
  input.value = 'Buy milk';
  input.dispatchEvent(new window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = 'Walk dog';
  input.dispatchEvent(new window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = 'Write code';
  input.dispatchEvent(new window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));

  const toggleAll = getToggleAll();
  if (toggleAll) {
    toggleAll.click();
  }
});

Then('all todos are marked as active', function () {
  const items = getTodoItems();
  for (const item of items) {
    if (item.classList.contains('completed')) {
      throw new Error('Some todos are still completed');
    }
  }
});

When('the user completes {string}', function (title) {
  const item = findTodoItem(title);
  if (!item) {
    throw new Error(`Todo "${title}" not found`);
  }
  const toggle = item.querySelector('.toggle');
  if (!toggle) {
    throw new Error(`Toggle not found for "${title}"`);
  }
  if (!toggle.checked) {
    toggle.click();
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = getToggleAll();
  if (!toggleAll) {
    throw new Error('Toggle-all checkbox not found');
  }
  if (!toggleAll.checked) {
    throw new Error('Toggle-all checkbox is not checked');
  }
});

// --- Deleting ---
When('the user clicks the destroy button on {string}', function (title) {
  const item = findTodoItem(title);
  if (!item) {
    throw new Error(`Todo "${title}" not found`);
  }
  const destroy = item.querySelector('.destroy');
  if (!destroy) {
    throw new Error(`Destroy button not found for "${title}"`);
  }
  destroy.click();
});

// --- Editing ---
When('the user double-clicks the label of {string}', function (title) {
  const item = findTodoItem(title);
  if (!item) {
    throw new Error(`Todo "${title}" not found`);
  }
  const label = item.querySelector('label');
  if (!label) {
    throw new Error(`Label not found for "${title}"`);
  }
  label.dispatchEvent(new window.MouseEvent('dblclick', { bubbles: true }));
});

Then('the editing input is shown for {string}', function (title) {
  const item = findTodoItem(title);
  if (!item) {
    throw new Error(`Todo "${title}" not found`);
  }
  if (!item.classList.contains('editing')) {
    throw new Error(`Todo "${title}" is not in editing mode`);
  }
  const editInput = item.querySelector('.edit');
  if (!editInput) {
    throw new Error(`Edit input not found for "${title}"`);
  }
});

Then('the editing input contains {string}', function (title) {
  const item = findTodoItem(title);
  if (!item) {
    throw new Error(`Todo "${title}" not found`);
  }
  const editInput = item.querySelector('.edit');
  if (!editInput) {
    throw new Error(`Edit input not found for "${title}"`);
  }
  if (editInput.value !== title) {
    throw new Error(
      `Expected edit input to contain "${title}", got "${editInput.value}"`
    );
  }
});

Given('the todo {string} is being edited', function (title) {
  loadApp();
  const input = getNewTodoInput();
  input.value = title;
  input.dispatchEvent(new window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));

  const item = findTodoItem(title);
  if (!item) {
    throw new Error(`Todo "${title}" not found`);
  }
  const label = item.querySelector('label');
  label.dispatchEvent(new window.MouseEvent('dblclick', { bubbles: true }));
