 * @planks("the user clicks the {string} filter link")
 * @planks("those items are {string} and {string}")
 * @planks("the {string} filter link has the selected class")
 * @planks("the active filter is selected")
 * @planks("the completed filter is selected")
 * @planks("the user toggles {string} back to active")
 * @planks("the todo list shows only active items")
 * @planks("the todo list shows {int} items")
 */
(function () {
  var STORAGE_KEY = 'todos-vanilla';
  var todoApp = document.querySelector('.todoapp');
  var newTodo = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var toggleAll = document.querySelector('.toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filters = document.querySelector('.filters');

  var todos = [];
  var filter = 'all';

  function load() {
    var stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      try {
        todos = JSON.parse(stored);
      } catch (e) {
        todos = [];
      }
    } else {
      todos = [];
    }
  }

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getFilter() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function filteredTodos() {
    var f = getFilter();
    if (f === 'active') return todos.filter(function (t) { return !t.completed; });
    if (f === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function activeCount() {
    var count = 0;
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) count++;
    }
    return count;
  }

  function completedCount() {
    return todos.length - activeCount();
  }

  function render() {
    var filtered = filteredTodos();
    var html = '';
    for (var i = 0; i < filtered.length; i++) {
      var todo = filtered[i];
      var completedClass = todo.completed ? ' class="completed"' : '';
      var checkedAttr = todo.completed ? ' checked' : '';
      html += '<li' + completedClass + ' data-id="' + todo.id + '">';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox"' + checkedAttr + '>';
      html += '<label>' + escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    }
    todoList.innerHTML = html;

    var hasTodos = todos.length > 0;
    main.style.display = hasTodos ? '' : 'none';
    footer.style.display = hasTodos ? '' : 'none';

    updateToggleAll();
    updateCount();
    updateClearCompleted();
    updateFilterLinks();
  }

  function escapeHtml(str) {
    return str
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  function updateToggleAll() {
    if (toggleAll) {
      toggleAll.checked = completedCount() === todos.length && todos.length > 0;
    }
  }

  function updateCount() {
    if (todoCount) {
      var count = activeCount();
      var word = count === 1 ? 'item' : 'items';
      todoCount.innerHTML = '<strong>' + count + '</strong> ' + word + ' left';
    }
  }

  function updateClearCompleted() {
    if (clearCompleted) {
      clearCompleted.style.display = completedCount() > 0 ? '' : 'none';
    }
  }

  function updateFilterLinks() {
    var f = getFilter();
    var links = filters.querySelectorAll('a');
    for (var i = 0; i < links.length; i++) {
      var link = links[i];
      var href = link.getAttribute('href');
      var isSelected = false;
      if (f === 'all' && href === '#/') isSelected = true;
      if (f === 'active' && href === '#/active') isSelected = true;
      if (f === 'completed' && href === '#/completed') isSelected = true;
      if (isSelected) {
        link.classList.add('selected');
      } else {
        link.classList.remove('selected');
      }
    }
  }

  function addTodo(title) {
    title = title.trim();
    if (title === '') return;
    var todo = {
      id: Date.now() + Math.random(),
      title: title,
      completed: false
    };
    todos.push(todo);
    save();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    save();
    render();
  }

  function toggleAllTodos() {
    var allCompleted = completedCount() === todos.length;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = !allCompleted;
    }
    save();
    render();
  }

  function destroyTodo(id) {
    var newTodos = [];
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id !== id) {
        newTodos.push(todos[i]);
      }
    }
    todos = newTodos;
    save();
    render();
  }

  function updateTodo(id, title) {
    title = title.trim();
    if (title === '') {
      destroyTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = title;
        break;
      }
    }
    save();
    render();
  }

  function clearCompletedTodos() {
    var newTodos = [];
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) {
        newTodos.push(todos[i]);
      }
    }
    todos = newTodos;
    save();
    render();
  }

  function getTodoId(el) {
    while (el && !el.dataset.id) {
      el = el.parentElement;
    }
    return el ? parseFloat(el.dataset.id) : null;
  }

  // Event handlers
  newTodo.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  todoList.addEventListener('change', function (e) {
    if (e.target.classList.contains('toggle')) {
      var id = getTodoId(e.target);
      if (id) toggleTodo(id);
    }
  });

  todoList.addEventListener('click', function (e) {
    if (e.target.classList.contains('destroy')) {
      var id = getTodoId(e.target);
      if (id) destroyTodo(id);
    }
    if (e.target.classList.contains('toggle')) {
      var id = getTodoId(e.target);
      if (id) toggleTodo(id);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var label = e.target.closest('label');
    if (!label) return;
    li.classList.add('editing');
    var edit = li.querySelector('.edit');
    if (edit) {
      edit.focus();
      edit.value = edit.value;
    }
  });

  todoList.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      var li = e.target.closest('li');
      if (!li || !li.classList.contains('editing')) return;
      var edit = li.querySelector('.edit');
      if (!edit) return;
      var id = getTodoId(li);
      if (id) {
        updateTodo(id, edit.value);
      }
    }
    if (e.key === 'Escape') {
      var li = e.target.closest('li');
      if (!li || !li.classList.contains('editing')) return;
      li.classList.remove('editing');
    }
  });

  todoList.addEventListener('blur', function (e) {
    if (e.target.classList.contains('edit')) {
      var li = e.target.closest('li');
      if (!li) return;
      var id = getTodoId(li);
      if (id) {
        updateTodo(id, e.target.value);
      }
    }
  }, true);

  if (toggleAll) {
    toggleAll.addEventListener('change', function () {
      toggleAllTodos();
    });
  }

  if (clearCompleted) {
    clearCompleted.addEventListener('click', function () {
      clearCompletedTodos();
    });
  }

  if (filters) {
    filters.addEventListener('click', function (e) {
      if (e.target.tagName === 'A') {
        // Let the hash change handle re-render
      }
    });
  }

  window.addEventListener('hashchange', function () {
    render();
  });

  // Initialize
  load();
  render();
})();

